var a=`0361-sachertorte`;var i=`world-0361`;var r=`AT`;var n=`western-europe`;var o=8;var l=125;var g={en:`Sachertorte`,ua:`Торт Захер`};var s={en:`A traditional Austria dish made with chicken egg, all-purpose flour, baking powder, heavy cream. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Австрія. Основні інгредієнти: куряче яйце, пшеничне борошно універсальне, розпушувач тіста, вершки високої жирності. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Melt the dark chocolate gently. Cream butter with sugar, beat in egg yolks, then fold in the cooled chocolate, flour and whipped whites to make a light batter.`,ua:`Обережно розтопіть шоколад. Збийте масло з цукром, введіть жовтки, охолоджений шоколад, борошно та збиті білки, щоб отримати пухке тісто.`,t:[`mixing`,`whisking`],m:12,i:[[`unsalted-butter`,210,`g`],[`white-granulated-sugar`,190,`g`],[`chicken-egg`,6,`pcs`],[`all-purpose-flour`,210,`g`],[`dark-chocolate`,230,`g`],[`baking-powder`,6,`g`]]},{en:`Bake in a preheated 180°C oven for about 47 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 47 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:47,i:[]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:8,i:[[`apricot-jam`,230,`g`]]},{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:8,i:[[`dark-chocolate`,220,`g`],[`heavy-cream`,160,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 50 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 50 хвилин.`,t:[`rapid-chilling`],m:50,i:[]}];var d={slug:a,id:i,country:`AT`,region:n,servings:8,minutes:125,title:g,text:s,steps:h};export{r as country,d as default,i as id,l as minutes,n as region,o as servings,a as slug,h as steps,s as text,g as title};